import{_ as n,C as t,o,c as p,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const s="/joinwell52/assets/execution-facts-20260915/pause-is-not-failure.figure.zh.svg",b=JSON.parse('{"title":"只是按了暂停，任务为什么被判出故障？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"只是按了暂停，任务为什么被判出故障？","date":"2026-09-15","published_date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"只是按了暂停，任务为什么被判出故障？","summary":"暂停应该只是先等一等，为什么恢复后任务还要人工处理？问题藏在一句丢失了原因的“现在不能继续”里。","cover":"/assets/execution-facts-20260915/pause-is-not-failure.cover-v1.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"固定源码有界实验；范围见正文","pageClass":"execution-facts-article"},"headers":[],"relativePath":"zh/engineering/2026-09-15-pause-is-not-failure.md","filePath":"zh/engineering/2026-09-15-pause-is-not-failure.md","lastUpdated":1789442662000}'),d={name:"zh/engineering/2026-09-15-pause-is-not-failure.md"};function c(u,e,h,g,m,_){const r=t("ArticleCover"),i=t("ArticleTableScroll");return o(),p("div",null,[a(r,{image:"/assets/execution-facts-20260915/pause-is-not-failure.cover-v1.png",kicker:"开源工程观察 · 实验研究",title:"只是按了暂停，任务为什么被判出故障？",summary:"暂停应该只是先等一等，为什么恢复后任务还要人工处理？问题藏在一句丢失了原因的“现在不能继续”里。",version:"2026-09-15",languageHref:"/en/engineering/2026-09-15-pause-is-not-failure",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=l('<h1 id="只是按了暂停-任务为什么被判出故障" tabindex="-1">只是按了暂停，任务为什么被判出故障？ <a class="header-anchor" href="#只是按了暂停-任务为什么被判出故障" aria-label="Permalink to &quot;只是按了暂停，任务为什么被判出故障？&quot;">​</a></h1><p>按下暂停，再按恢复，你大概会期待原来的工作继续排队。</p><p>如果恢复后，一批任务却被标成“出了问题，需要人工处理”，就很容易让人觉得：是不是暂停把任务弄坏了？</p><p>这个反常的现象，来自一个 AI 团队管理工具的修复提案。它让我们注意到：<strong>“现在不能继续”有很多原因，把原因丢掉，等待就可能变成故障。</strong></p><h2 id="都是不能开始-后续却应该不同" tabindex="-1">都是不能开始，后续却应该不同 <a class="header-anchor" href="#都是不能开始-后续却应该不同" aria-label="Permalink to &quot;都是不能开始，后续却应该不同&quot;">​</a></h2><p>Paperclip 用来组织 AI 助手和工作任务。它把一组助手与任务称为“公司”，这里可以把它理解为一个 AI 团队。</p><p>MrBlackTongue 在<a href="https://github.com/paperclipai/paperclip/pull/13443" target="_blank" rel="noreferrer">这份修复提案</a>中报告：团队处于暂停状态时，自动检查未完成任务的程序，可能把任务按预算不足升级处理。这里的预算，是团队或助手被允许使用的费用额度。</p><p>暂停和额度不足，确实都能阻止新工作开始。但用户接下来要做的事不同：主动暂停，通常希望稍后恢复；额度不足，则可能需要调整额度或决定是否继续。</p><p>我们自己也在开发协作系统，所以对这个来源感兴趣。值得验证的是：程序到底根据什么，把“先等一等”变成了“有个问题要处理”？</p><h2 id="原因原本在-中途却被省略了" tabindex="-1">原因原本在，中途却被省略了 <a class="header-anchor" href="#原因原本在-中途却被省略了" aria-label="Permalink to &quot;原因原本在，中途却被省略了&quot;">​</a></h2><p>负责检查的程序本来会返回阻止启动的具体情况，例如“团队暂停”或“费用额度不足”。</p><p>但下一段恢复程序只留下了一个简单答案：有阻碍，或者没有阻碍。只要有阻碍，就走进按预算问题处理的分支。</p><p>这就像一份说明原本写着“今天暂停，明天再做”，转交时只剩下“今天做不了”。后面的人如果按自己的猜测补上“因为没钱了”，处理方向就变了。这个比喻只说明信息怎样丢失；真正的程序中，被省略的是阻止执行的原因。</p><p>候选修复让原因一起传下来，并在处理每条任务前，查看团队是不是已经暂停。</p><p>不过，只在开头看一眼，还不够。</p><h2 id="三个时刻-为什么会得出相反结论" tabindex="-1">三个时刻，为什么会得出相反结论？ <a class="header-anchor" href="#三个时刻-为什么会得出相反结论" aria-label="Permalink to &quot;三个时刻，为什么会得出相反结论？&quot;">​</a></h2><p>团队状态会在程序检查期间改变。我们专门安排了这样一个顺序：</p><ol><li>开始检查时，团队还在运行。</li><li>随后团队暂停，后面的检查读到了“因为暂停，不能开始”。</li><li>等程序决定怎样处理时，团队又恢复了。</li></ol><p>第三步如果重新查询，会看见“正在运行”。可是，这不能推翻第二步的事实：<strong>刚才那次不能开始，确实是因为暂停。</strong></p><p>候选修复使用那次检查带回的原因，而不再拿稍后的状态倒推之前发生了什么。</p><p><img src="'+s+'" alt="后来的恢复，不能改写刚才暂停的原因"></p><p><em>图 1：原因跟着当次检查结果传递。来源：本轮 paperclip.json 中控制了先后顺序的实验；不是实际多人同时操作的测量。</em></p><h2 id="我们记录程序选了哪条路" tabindex="-1">我们记录程序选了哪条路 <a class="header-anchor" href="#我们记录程序选了哪条路" aria-label="Permalink to &quot;我们记录程序选了哪条路&quot;">​</a></h2><p>实验使用原来的预算判断代码和相关恢复分支，让测试程序返回预先安排的状态，并记录它选择“等待”还是“按额度问题处理”。<strong>没有真的把任务写进数据库，也没有跑完整的任务恢复系统。</strong></p><table tabindex="0"><thead><tr><th>我们安排的情况</th><th>原代码的选择</th><th>候选修复的选择</th></tr></thead><tbody><tr><td>开始时团队已经暂停</td><td>按额度问题处理</td><td>跳过，暂不处理</td></tr><tr><td>开头检查后才暂停</td><td>按额度问题处理</td><td>跳过，暂不处理</td></tr><tr><td>读到暂停原因后立即恢复</td><td>按额度问题处理</td><td>仍按当次暂停原因跳过</td></tr><tr><td>团队运行中，确实超出额度</td><td>按额度问题处理</td><td>仍按额度问题处理</td></tr><tr><td>团队运行中，某助手因额度暂停</td><td>按额度问题处理</td><td>仍按额度问题处理</td></tr><tr><td>没有阻止启动的情况</td><td>继续后面的检查</td><td>继续后面的检查</td></tr><tr><td>整个团队因额度原因被暂停</td><td>按额度问题处理</td><td>先尊重团队暂停，跳过</td></tr></tbody></table><p>七组对照说明，修复没有把所有问题都变成等待：团队仍在运行、但确实存在额度问题时，原有处理保留了。</p><p>最后一行也有区别。如果整个团队已经暂停，候选先尊重这个整体状态，不在这轮检查里逐项升级任务。</p><h2 id="跳过以后-什么时候再回来" tabindex="-1">跳过以后，什么时候再回来？ <a class="header-anchor" href="#跳过以后-什么时候再回来" aria-label="Permalink to &quot;跳过以后，什么时候再回来？&quot;">​</a></h2><p>到这里，我们确认的是：受测代码不会再把这些暂停场景混成预算问题。</p><p>但“这次先跳过”还不是故事的终点。恢复以后，任务能不能及时被重新检查？会不会从误报故障，变成一直没人继续处理？这些都需要把完整恢复过程跑起来，进一步验证。</p><p>这也是下一步应追问的问题：<strong>怎样既记住“刚才为什么停下”，又能在条件改变以后及时重新开始检查？</strong></p><p>对于开发者，可以从状态传递的每一步检查：原因有没有丢失，处理时是否拿了另一个时刻的状态来猜？对于使用者，恢复按钮按下后，你希望看到哪些任务继续等待、哪些还需要你处理，以及各自的原因？</p><p>暂停应该给人一个可理解的等待状态。保存原因，正是让这种等待可以解释、也可以继续处理的第一步。</p><details><summary>实验版本、范围与复核入口</summary><p>固定前身 0e9b24c 与候选 1db5d93，提取原 getInvocationBlock、预算阻塞恢复分支及候选暂停预检；数据库查询使用可控行替身，升级动作由记录器接住。七场景、两版本，共十四条观察。</p><p>表格里的“按额度问题处理”表示请求调用预算阻塞升级逻辑；“跳过”表示跳过当前候选任务；“继续后面的检查”只表示通过这一分支。它们都不等于真实任务数据库状态已经改变或任务最终恢复成功。暂停原因标识为 company_paused，真实预算阻塞标识为 budget_exhausted。</p><p>本轮没有执行 PostgreSQL 集成测试、真实并发工作人员、事务或恢复后的下一轮扫描。上游报告的批量事故不是我们的实验样本，也未据此确认 CodeFlowMu 存在相同问题。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-15-execution-facts" target="_blank" rel="noreferrer">完整源码来源、探针、结果与复跑方法</a>。</p></details>',34))])}const x=n(d,[["render",c]]);export{b as __pageData,x as default};
